library TickState {

    /// @dev Compute fee growth for the position for the epoch using tick-indexed state for token0 up to specified epoch.
    function computeFeeGrowth0TillEpoch(
        address historyTrackerAddress,
        address pool,
        uint256 epoch,
        int24 tickLower,
        int24 tickUpper
    ) internal view returns (uint256) {
        (, int24 tick) = PoolSnapshotHelper.getPoolPriceAndTickAtEpoch(address(historyTrackerAddress), pool, epoch);
        IHistoryStateTrackerBase historyTracker = IHistoryStateTrackerBase(historyTrackerAddress);
        // fg
        uint256 feeGrowthGlobal = historyTracker.stateOfAt(
            PoolSnapshotHelper.getPoolSnapshotKey(PoolSnapshotHelper.SnapshotType.FeeGrowthGlobal0X128, pool),
            epoch
        );

        uint256 tickUpperFeeGrowthOutside = historyTracker.stateOfAt(
            PoolSnapshotHelper.getTickSnapshotKey(
                PoolSnapshotHelper.SnapshotType.TickFeeGrowthOutside0X128ForEpoch,
                pool,
                tickUpper
            ),
            epoch
        );
        uint256 tickLowerFeeGrowthOutside = historyTracker.stateOfAt(
            PoolSnapshotHelper.getTickSnapshotKey(
                PoolSnapshotHelper.SnapshotType.TickFeeGrowthOutside0X128ForEpoch,
                pool,
                tickLower
            ),
            epoch
        );

        // fa
        uint256 feeGrowthTicksUp;
        // fb
        uint256 feeGrowthTicksDown;

        if (tick >= tickLower) {
            feeGrowthTicksDown = tickLowerFeeGrowthOutside;
        } else {
            /// underflow is allowed here, wrap-around subtraction (mod 2^256)
            feeGrowthTicksDown = feeGrowthGlobal - tickLowerFeeGrowthOutside;
        }

        if (tick < tickUpper) {
            feeGrowthTicksUp = tickUpperFeeGrowthOutside;
        } else {
            // underflow is allowed here, wrap-around subtraction (mod 2^256)
            feeGrowthTicksUp = feeGrowthGlobal - tickUpperFeeGrowthOutside;
        }

        // underflow is allowed here, wrap-around subtraction (mod 2^256)
        return feeGrowthGlobal - feeGrowthTicksDown - feeGrowthTicksUp;
    }

    /// @dev Compute fee growth for the position for the epoch using tick-indexed state for token1.
    function computeFeeGrowth1TillEpoch(
        address historyTrackerAddress,
        address pool,
        uint256 epoch,
        int24 tickLower,
        int24 tickUpper
    ) internal view returns (uint256) {
        (, int24 tick) = PoolSnapshotHelper.getPoolPriceAndTickAtEpoch(address(historyTrackerAddress), pool, epoch);
        IHistoryStateTrackerBase historyTracker = IHistoryStateTrackerBase(historyTrackerAddress);

        // fg
        uint256 feeGrowthGlobal = historyTracker.stateOfAt(
            PoolSnapshotHelper.getPoolSnapshotKey(PoolSnapshotHelper.SnapshotType.FeeGrowthGlobal1X128, pool),
            epoch
        );

        uint256 tickUpperFeeGrowthOutside = historyTracker.stateOfAt(
            PoolSnapshotHelper.getTickSnapshotKey(
                PoolSnapshotHelper.SnapshotType.TickFeeGrowthOutside1X128ForEpoch,
                pool,
                tickUpper
            ),
            epoch
        );
        uint256 tickLowerFeeGrowthOutside = historyTracker.stateOfAt(
            PoolSnapshotHelper.getTickSnapshotKey(
                PoolSnapshotHelper.SnapshotType.TickFeeGrowthOutside1X128ForEpoch,
                pool,
                tickLower
            ),
            epoch
        );

        // fa
        uint256 feeGrowthTicksUp;
        // fb
        uint256 feeGrowthTicksDown;

        if (tick >= tickLower) {
            feeGrowthTicksDown = tickLowerFeeGrowthOutside;
        } else {
            // underflow is allowed here, wrap-around subtraction (mod 2^256)
            feeGrowthTicksDown = feeGrowthGlobal - tickLowerFeeGrowthOutside;
        }

        if (tick < tickUpper) {
            feeGrowthTicksUp = tickUpperFeeGrowthOutside;
        } else {
            // underflow is allowed here, wrap-around subtraction (mod 2^256)
            feeGrowthTicksUp = feeGrowthGlobal - tickUpperFeeGrowthOutside;
