import { TransparentUpgradeableProxy } from "@openzeppelin/contracts/proxy/TransparentUpgradeableProxy.sol";

/// @title The interface for the EnosysDex V3 Factory
/// @notice The EnosysDex V3 Factory facilitates creation of EnosysDex V3 pools and control over the protocol fees
interface IEnosysDexV3Factory {
    /// @notice Emitted when the owner of the factory is changed
    /// @param oldOwner The owner before the owner was changed
    /// @param newOwner The owner after the owner was changed
    event OwnershipTransferred(address indexed oldOwner, address indexed newOwner);

    /// @notice Emitted when the governor of the factory is changed
    /// @param governorAddress The address of the new governor
    event SetGovernor(address governorAddress);

    /// @notice Emitted when a pool is created
    /// @param token0 The first token of the pool by address sort order
    /// @param token1 The second token of the pool by address sort order
    /// @param fee The fee collected upon every swap in the pool, denominated in hundredths of a bip
    /// @param tickSpacing The minimum number of ticks between initialized ticks
    /// @param pool The address of the created pool
    event PoolCreated(
        address indexed token0,
        address indexed token1,
        uint24 indexed fee,
        int24 tickSpacing,
        address pool
    );

    /// @notice Emitted when a new fee amount is enabled for pool creation via the factory
    /// @param fee The enabled fee, denominated in hundredths of a bip
    /// @param tickSpacing The minimum number of ticks between initialized ticks for pools created with the given fee
    event FeeAmountEnabled(uint24 indexed fee, int24 indexed tickSpacing);

    /// @notice Emitted when the pool implementation is updated
    /// @param poolImplementation The address of the new pool implementation contract
    event SetPoolImplementation(address indexed poolImplementation);

    /// @notice Emitted when the poolsProxyAdmin is updated
    /// @param proxyAdmin The address of the new poolsProxyAdmin contract
    event SetPoolsProxyAdmin(address indexed proxyAdmin);

    /// @notice Emitted when the ftsoRewardRedistributor address is updated
    /// @param _ftsoRewardRedistributor The address of the new ftsoRewardRedistributor contract
    event UpdateFtsoRewardRedistributor(address indexed _ftsoRewardRedistributor);

    /// @notice Emitted when the monthlyAirdropRedistributor address is updated
    /// @param _monthlyAirdropRedistributor The address of the new monthlyAirdropRedistributor contract
    event UpdateMonthlyAirdropRedistributor(address indexed _monthlyAirdropRedistributor);

    /// @notice Emitted when the wnatRegistry address is updated
    /// @param _wnatRegistry The address of the new wnatRegistry contract
    event UpdateWnatRegistry(address indexed _wnatRegistry);

    /// @notice Emitted when a trackable asset is added
    /// @param token The address of the trackable asset
    event TrackableAssetAdded(address indexed token);

    /// @notice Emitted when the protocol fee is updated
    /// @param protocolFee The new protocol fee
    event UpdateProtocolFee(uint8 indexed protocolFee);

    /// @notice Emitted when the feeReceiver address is updated
    /// @param _feeReceiver The address of the new feeReceiver
    event UpdateFeeReceiver(address indexed _feeReceiver);

    /// @notice Emitted when the protocol fees collection from a pool is skipped due to unexpected error
    /// @param pool The address of the pool
    event SkippedCollectProtocolFees(address indexed pool);

    /// @notice Returns the current owner of the factory
    /// @dev Can be changed by the current owner via transferOwnership
    /// @return The address of the factory owner
    function owner() external view returns (address);

    /// @notice Returns the current governor of the factory
    /// @dev Can be changed by the current governor via setGovernor
    /// @return The address of the factory governor
    function governor() external view returns (address);

    /// @notice Returns the address of the FTSO Reward Redistributor contract
    /// @return The address of the FTSO Reward Redistributor contract
    function ftsoRewardRedistributor() external view returns (address);

    /// @notice Returns the address of the Monthly Airdrop Redistributor contract
    /// @return The address of the Monthly Airdrop Redistributor contract
    function monthlyAirdropRedistributor() external view returns (address);

    /// @notice Returns the value of the default protocol fee
    /// @dev The default protocol fee is the fee same for token0 and token1
    /// @dev Can be changed by the current owner
    /// @return The default protocol fee
    function protocolFee() external view returns (uint8);

    /// @notice The address of the Enosys's ProfitDistribution contract
    /// that receives the protocol fees from the pools
    /// @return The address of the protocolFeeReceiver
    function protocolFeeReceiver() external view returns (address);

    /// @notice Returns the address of the History State Tracker by Block contract
    /// @return The address of the History State Tracker contract
    function historyStateTrackerByBlock() external view returns (address);

    /// @notice Returns the address of the History State Tracker by Epoch contract
    /// @return The address of the History State Tracker contract
    function historyStateTrackerByEpoch() external view returns (address);

    /// @notice Returns the tick spacing for a given fee amount, if enabled, or 0 if not enabled
    /// @dev A fee amount can never be removed, so this value should be hard coded or cached in the calling context
    /// @param fee The enabled fee, denominated in hundredths of a bip. Returns 0 in case of unenabled fee
    /// @return The tick spacing
    function feeAmountTickSpacing(uint24 fee) external view returns (int24);

    /// @notice Returns the pool address for a given pair of tokens and a fee, or address 0 if it does not exist
    /// @dev tokenA and tokenB may be passed in either token0/token1 or token1/token0 order
    /// @param tokenA The contract address of either token0 or token1
    /// @param tokenB The contract address of the other token
    /// @param fee The fee collected upon every swap in the pool, denominated in hundredths of a bip
    /// @return pool The pool address
    function getPool(
        address tokenA,
        address tokenB,
        uint24 fee
    ) external view returns (address pool);

    /// @return The address of the pool by pool index
    function pools(uint256 index) external view returns (address);
    /// @return If the pool is deployed by the factory
    function isPoolDeployedByFactory(address pool) external view returns (bool);

    /// @notice Returns the number of pools created by the factory
    function poolsCount() external view returns (uint256);

    /// @notice Returns the address of all created pool by the factory
    function getPools() external view returns (address[] memory);

    /// @notice Return if the asset balance change should be tracked
    /// @return true if the asset is trackable
    function isTrackableAsset(address asset) external view returns (bool);

    /// @notice Creates a pool for the given two tokens and fee
    /// @param tokenA One of the two tokens in the desired pool
    /// @param tokenB The other of the two tokens in the desired pool
    /// @param fee The desired fee for the pool
    /// @dev tokenA and tokenB may be passed in either order: token0/token1 or token1/token0. tickSpacing is retrieved
    /// from the fee. The call will revert if the pool already exists, the fee is invalid, or the token arguments
    /// are invalid.
    /// @dev Must be called by the current owner or governor
    /// @return pool The address of the newly created pool
    function createPool(
        address tokenA,
        address tokenB,
        uint24 fee
    ) external returns (address pool);

    /// @notice Initializes the factory
    /// @dev _poolImplementation, _poolsProxyAdmin and _feeReceiver can be zero addresses and can be set later
    /// @param _governor The address of the governor
    /// @param _poolImplementation The address of the pool implementation contract
    /// @param _poolsProxyAdmin The address of the proxy admin for pool
    /// @param _historyStateTrackerByEpoch_ The address of history state tracker contract
    /// @param _historyStateTrackerByBlock_ The address of history state tracker contract
    /// @param _ftsoRewardRedistributor The address of the FTSO Reward Redistributor contract
    /// @param _monthlyAirdropRedistributor The address of the Monthly Airdrop Redistributor contract
    /// @param _wnatRegistry The address of the WNat Registry contract
    /// @notice _poolImplementation acan be zero addresses and can be set later
    /// @param _protocolFee The default protocol fee
    /// @param _protocolFeeReceiver The address of the Enosys's ProfitDistribution contract
    function initialize(
        address _governor,
        address _poolImplementation,
        address _poolsProxyAdmin,
        address _historyStateTrackerByEpoch_,
        address _historyStateTrackerByBlock_,
        address _ftsoRewardRedistributor,
        address _monthlyAirdropRedistributor,
        address _wnatRegistry,
        uint8 _protocolFee,
        address _protocolFeeReceiver
    ) external;

    /// @notice Collects protocol fees from all pools defined by start index and count
    /// @dev Can be called by anyone if protocol fee receiver is set
    /// @dev It will update all pools starting from `startPoolIndex` to the last one 
    /// if pass 0 or any big amount that is bigger than pools count in range as `count`
    /// @param startPoolIndex The index of the first pool to collect fees from
    /// @param count The number of pools to collect fees from
    function collectProtocolFees(uint startPoolIndex, uint count) external;

    /// @notice Collects protocol fees from all pools
    function collectProtocolFeesAll() external;

    /// @notice Sets the governor of the factory
    /// @dev Must be called by the current governor
    /// @param governorAddress The address of the new governor
    function setGovernor(address governorAddress) external;

    /// @notice Updates the owner of the factory
    /// @dev Must be called by the current owner
    /// @param _owner The new owner of the factory
    function transferOwnership(address _owner) external;

    /// @notice Enables a fee amount with the given tickSpacing
    /// @dev Fee amounts may never be removed once enabled
    /// @dev Must be called by the current governor
    /// @param fee The fee amount to enable, denominated in hundredths of a bip (i.e. 1e-6)
    /// @param tickSpacing The spacing between ticks to be enforced for all pools created with the given fee amount
    function enableFeeAmount(uint24 fee, int24 tickSpacing) external;

    /// @notice Update the value of the default protocol fee
    /// @dev Can be called by the current governor
    /// @dev Can be a zero value (protocol fee disabled)
    /// @param _protocolFee The new default protocol fee
    /// @param updateAllPools Whether to update the protocol fee for all pools
    function updateProtocolFee(uint8 _protocolFee, bool updateAllPools) external;

    /// @notice Update the address of the Protocol fee receiver
    /// @dev Reverts if the caller is not the governor
    /// @dev Reverts if the new protocol fee receiver is the same as the current one
    /// @param _protocolFeeReceiver The address of the new protocol fee receiver
    function updateProtocolFeeReceiver(address _protocolFeeReceiver) external;

    /// @notice Sets the default pool implementation contract
    /// @param _poolImplementation The address of the pool implementation contract
    function setPoolImplementation(address _poolImplementation) external;

    /// @notice Update the implementation for a single provided pool
    /// @param _pool The address of the pool to update
    function updatePoolImplementation(TransparentUpgradeableProxy _pool) external;

    /// @notice Update the implementation for a list of provided pools
    /// @param _pools The addresses of the pools to update
    function updatePoolsImplementation(TransparentUpgradeableProxy[] memory _pools) external; 

    /// @notice Update the implementation for all pools in the provided range
    /// @dev It will update all pools starting from `startPoolIndex` to the last one 
    /// if pass 0 or any big amount that is bigger than pools count in range as `count`
    /// @param startPoolIndex The index of the first pool to update
    /// @param count The number of pools to update
    function updatePoolsImplementation(uint startPoolIndex, uint count) external;

    /// @notice Update the implementation for all pools
    function updateAllPoolsImplementation() external; 

    /// @notice Update the proxy admin contract for provided pools
    /// @param _pools The addresses of the pools to update
    /// @param _newProxyAdmin The address of the new proxy admin contract
    /// @param _setAsDefaultProxyAdmin Whether to set the new proxy admin as the default proxy admin
    function updatePoolsProxyAdmin(TransparentUpgradeableProxy[] memory _pools, address _newProxyAdmin, bool _setAsDefaultProxyAdmin) external;

    /// @notice Update Ftsos Reward Redistributor contract address
    /// @param _ftsoRewardRedistributor The address of the new ftsoRewardRedistributor contract
    function updateFtsoRewardRedistributor(address _ftsoRewardRedistributor) external;

    /// @notice Update Monthly Airdrop Redistributor contract address
    /// @param _monthlyAirdropRedistributor The address of the new monthlyAirdropRedistributor contract
    function updateMonthlyAirdropRedistributor(address _monthlyAirdropRedistributor) external;

    /// @notice Update WNat Registry contract address
    /// @param _wnatRegistry The address of the new wnatRegistry contract
    function updateWnatRegistry(address _wnatRegistry) external;

    /// @notice Update the address of the pool proxy admin
    /// @param _proxyAdmin The address of the new pool proxy admin
    function setPoolsProxyAdmin(address _proxyAdmin) external;

    /// @notice Add a token, balance change of which on pools should be tracked
    /// @param asset The address of the token
    function addTrackableAsset(address asset) external;
}

